    "_id": `art-import-1`,
    "title": `Комплексное сопровождение станков S.Gothard – от поставки и монтажа до сервисного обслуживания`,
    "slug": `kompleksnoe-soprovozhdenie-stankov-s-gothard-ot-postavki-i-montazha-do-servisnogo-obsluzhivaniya`,
    "excerpt": `Компания «АВТОграф Инструментальные Решения» обеспечивает полное сопровождение поставляемого станочного оборудования S.Gothard во всех регионах России. Осуществив ввод станков в эксплуатацию и завершив проект, компания продолжает оказывать предприятию-заказчику всю необходимую поддержку, включая консультации и помощь в настройке, поставку расходных материалов, инструмента и СОЖ, проведение регламентных работ.`,
    "mainImage": `/news/kompleksnoe-soprovozhdenie-stankov-s-gothard-ot-postavki-i-montazha-do-servisnogo-obsluzhivaniya.jpg`,
    "content": `Современные обрабатывающие центры, как и любое технически сложное оборудование, требует регулярного сервисного обслуживания. Как правило, это предполагает диагностику и настройку всех систем, проверку узлов, замену изношенных деталей и расходников, чистку и смазку движущихся частей.

Выполнение плановых работ позволяет поддерживать станочное оборудование в работоспособном состоянии, обеспечивая стабильно высокую точность обработки изделий. При этом, устранение на ранних стадиях мелких проблем позволяет избежать простоя оборудования из-за внезапной поломки и дорогостоящего ремонта. В целом, профессиональное регулярное обслуживание позволяет существенно продлить срок службы станка.

Одним из примеров поддержки, которую «АВТОграф Инструментальные Решения» предоставляет предприятиям-заказчикам во всех регионах страны, могут послужить сервисные работы по обслуживанию станков S.Gothard, недавно выполненные компанией на одном из производств в Московской области.

Данное производственное предприятие сотрудничает с компанией «АВТОграф Инструментальные Решения» далеко не первый год.

За прошедшее время специалистами компании в цехах предприятия была введена в эксплуатацию большая группа фрезерных и токарных обрабатывающих центров по металлу с числовым программным управлением S.Gothard.

Наиболее востребованным на производстве стал вертикально-фрезерный обрабатывающий центр с ЧПУ S.Gothard SGT-MC9050.

Обрабатывающий центр оснащен шпинделем с патроном BT40, который обеспечивает надежную фиксацию инструмента и имеет канал для подачи смазочно-охлаждающей жидкости (СОЖ). Скорость вращения шпинделя – до 12 000 об/мин.

Габариты обрабатывающего центра составляют 2950 х 2300 х 2650 мм (ДхШхВ), масса – около 7 тонн. Перемещение режущего инструмента по осям X / Y / Z составляет 900 / 500 / 550 мм, скорость рабочих перемещений: 1-10000 мм/мин.

Станок SGT-MC9050 работает под управлением системы Fanuc и снабжен дисковым инструментальным магазином, позволяющим задействовать 24 сменных инструмента, замена которых производится манипулятором. Для очистки инструмента от металлических опилок и стружки перед установкой в патрон используется система воздушного обдува.

Точность позиционирования инструмента (т.е. допустимая величина отклонения фактического положения резца от заданной в системе ЧПУ координаты) по осям X / Y / Z находится в пределах 5 микрон, точность повторяемости операций (т.е. возвращения рабочего инструмента в одну и ту же точку из различных положений с минимальным отклонением) – до 3 микрон.

Наряду с реализацией новых проектов по поставке и вводу в эксплуатацию новых станков, компания «АВТОграф Инструментальные Решения» снабжает предприятие сменным инструментом и СОЖ, производит регламентные и другие работы.

В рамках недавнего выезда на предприятие в Московскую область сервисные инженеры компании провели диагностику, техническое обслуживание и настройку вертикально-фрезерных обрабатывающих центров S.Gothard SGT-MC9050 и токарного обрабатывающего центра с ЧПУ S.Gothard SGT-LC2140D.

Выполнение данных работ позволит не только предотвратить поломки или отказы станочного оборудования в ходе дальнейшей эксплуатации, но и обеспечить заданную точность и качество обработки изделий, что особенно важно для стабильного функционирования производства.`,
    "author": `Редакция`,
