    "seoTitle": `Флагманы российской металлургии выбирают станки S.Gothard`,
    "seoDescription": `Компания «АВТОграф Инструментальные Решения» реализовала проект по оснащению токарными обрабатывающими центрами S.Gothard производственного участка одного из лидеров российской металлургии АО «Уральская Сталь». Компания «АВТОграф Инструментальные Решения» обеспечила весь комплекс инжиниринговых работ – от предпроектной проработки до ввода оборудования в штатную эксплуатацию.`
