    "excerpt": `Запуск современного обрабатывающего центра по металлу S.Gothard SGT-MC9050 стал знаковой вехой развития опытного производства одной из ведущих московских научно-производственных компаний. Поставку, подключение и пусконаладку станочного оборудования обеспечила компания «АВТОграф Инструментальные Решения».`,
