    "seoDescription": `Универсальные фрезерные станки S.Gothard находят широкое применение на производственных предприятиях различного масштаба – от небольших слесарных и ремонтных мастерских до промышленных гигантов. Одним из последних примеров может послужить проект модернизации производственных мощностей машиностроительного завода в Казани.`
