    "title": `Тульская область. Завод энергомашиностроения. Новый обрабатывающий центр введен в эксплуатацию`,
    "slug": `tulskaya-oblast-zavod-energomashinostroeniya-novyy-obrabatyvayuschiy-tsentr-vveden-v-ekspluatatsiyu`,
    "excerpt": `На заводе энергомашиностроения в Тульской области состоялся запуск нового фрезерного обрабатывающего центра по металлу SGT-MCH1890 S.Gothard. Весь комплекс задач – от поставки до пусконаладочных работ – был выполнен компанией «АВТОграф Инструментальные Решения».`,
    "mainImage": `/news/tulskaya-oblast-zavod-energomashinostroeniya-novyy-obrabatyvayuschiy-tsentr-vveden-v-ekspluatatsiyu.jpg`,
    "content": `Энергомашиностроительный завод в Тульской области специализируется в области производства узлов и комплектующих для компрессорных и газопроводных станций.

Планомерно занимаясь техническим перевооружением производства, завод активно внедряет новое оборудование. Одним из таких шагов, позволивших существенно расширить ассортимент и повысить конкурентоспособность продукции, стал ввод современного вертикально-фрезерного обрабатывающего центра SGT-MCH1890 S.Gothard , поставленного компанией «АВТОграф Инструментальные Решения».

Фрезерный обрабатывающий центр по металлу SGT-MCH1890, оснащенный системой управления Fanuc, обеспечивает обработку металлических деталей с высокой точностью и эффективностью. Погрешность позиционирования инструмента при выполнении производственных операций составляет менее 5 микрон, погрешность повторяемости по осям (т.е. точность, с которой станок подает инструмент в одну и ту же позицию) – менее 3 микрон.

Реализация проекта потребовала решения целого ряда нестандартных задач. Так из-за больших габаритов фрезерный центр SGT-MCH1890 S.Gothard пришлось доставлять на объект в Тульской области в разобранном виде.

Тем не менее, выездная бригада «АВТОграф Инструментальные Решения» с успехом выполнила сборку металлообрабатывающего центра непосредственно в заводском цеху. Задача была выполнена в достаточно короткие сроки.

После этого специалисты компании приступили к запуску оборудования в эксплуатацию. Данный процесс включал в себя несколько этапов. Прежде всего были выполнены работы по подключению фрезерного центра к электросети, сжатому воздуху и другим необходимым инженерным коммуникациям.

Важным этапом стало обучение персонала на предприятии, которое включало инструктаж по безопасному использованию металлорежущего станка SGT-MCH1890 S.Gothard, изучению основных принципов его работы и техническое обслуживание.

На сегодняшний день обрабатывающий центр функционирует в штатном режиме, обеспечивая производство деталей и комплектующих для газовых и паровых турбин, компрессоров и другого оборудования, используемого на объектах топливно-энергетического комплекса нашей страны.`,
