    "excerpt": `Компания «АВТОграф Инструментальные Решения» представила новую линейку наборов метчиков и плашек Debever Machining Solutions для нарезания метрической резьбы. Все инструменты выполнены из инструментальной стали, и могут использоваться как для домашнего ремонта, так и в профессиональной сфере.`,
