    "excerpt": `Металлообрабатывающие станки S.Gothard – благодаря высокой точности, надежности и автоматизации – пользуются стабильным спросом на предприятиях машиностроения. Не случайно, фрезерные обрабатывающие центры именно этого бренда были выбраны для модернизации производственных мощностей одного из крупных машиностроительных заводов Московской области.`,
