    "excerpt": `Масштабный проект по оснащению современными станками одного из ведущих машиностроительных предприятий в Казани выходит на финишную прямую. В январе сервисные инженеры компании «АВТОграф Инструментальные Решения» выполнили пусконаладочные работы и обеспечили ввод в эксплуатацию еще нескольких фрезерных центров S.Gothard.`,
