    "excerpt": `1 декабря состоялось торжественное открытие новых учебных мастерских машиностроительного отделения Шадринского политехнического колледжа. Мастерские оснащены новейшим фрезерным обрабатывающим центром S.Gothard, которые поставляются компанией «АВТОграф Инструментальные Решения» и другим передовым технологическим оборудованием. Посетив Шадринский колледж, губернатор Курганской области Вадим Шумков высоко оценил качество и современный уровень учебной базы, позволяющей готовить высококвалифицированных рабочих и специалистов.`,
    "mainImage": `/news/studenty-mashinostroiteli-iz-shadrinska-budut-uchitsya-na-samom-sovremennom-oborudovanii.jpg`,
    "content": `Шадринский политехнический колледж – одно из ведущих учреждений среднего профессионального образования Курганской области.

Сегодня здесь учится более 1500 студентов, проходя обучение по специальностям, наиболее востребованным на предприятиях машиностроения, транспорта и логистики, строительства, агропромышленного комплекса и других отраслей экономики.

Для того, чтобы молодые специалисты могли получать качественное образование и приобретать навыки работы с современным оборудованием, в колледже ведётся планомерное обновление учебной базы.

В текущем году, в рамках госпрограммы модернизации учреждений профессионального образования, в Шадринском колледже был выполнен капитальный ремонт учебного корпуса машиностроительного отделения. Проведены работы по оснащению и комплектации современным производственным оборудованием, инструментом и компьютерной техникой мастерских по направлениям «Фрезерные работы на станках с ЧПУ», «Сварочные технологии» и «Аддитивное производство».

Посетив Шадринский политехнический колледж, губернатор Курганской области Вадим Шумков и глава Шадринска Антон Мокан ознакомились с результатами капремонта и модернизации машиностроительного учебного корпуса.

Рассказывая гостям и прессе о выполненных работах, директор Шадринского политехнического колледжа Михаил Харлов отметил: «Отремонтировано все здание: обновили кровлю и фасад, заменили систему отопления, электропроводку и вентиляцию. Сейчас у нас есть новейший фрезерный станок с ЧПУ и сварочный агрегат. Ребята будут изучать все виды сварки, работу на станках и проектировать детали для машиностроения».

Осмотрев мастерские и учебные классы, и по достоинству оценив уровень оснащения, губернатор Вадим Шумков подытожил: «Ребят теперь будут готовить по последнему слову техники». Он также выразил уверенность, что у выпускников колледжа будут отличные перспективы трудоустройства и профессионального роста на лучших предприятиях реального сектора экономики.

Как отмечалось выше, весомый вклад в оснащение Шадринского колледжа современным производственным оборудованием внесла компания «АВТОграф Инструментальные Решения». В первую очередь речь идет о новейшем фрезерном трёхосевом обрабатывающем центре с ЧПУ SGT-MC84Q бренда S.Gothard.

Специалисты компании «АВТОграф Инструментальные Решения», которая является эксклюзивным представителем и поставщиком S. Gothard в России, выполнили доставку, монтаж и настройку фрезерного станочного комплекса, ознакомили с особенностями оборудования преподавателей колледжа.

В новых мастерских студенты-машиностроители смогут освоить все необходимые технологические операции от программирования станков с ЧПУ до изготовления корпусных и других деталей.

Таким образом, уровень их профессиональной подготовки будет полностью соответствовать самым современным отраслевым требованиям и молодые машиностроители из Шадринска смогут без особых затруднений найти перспективную работу на ведущих производствах страны.`,
