    "title": `«Движок Прогресса» показал высокий уровень подготовки петербургских студентов`,
    "slug": `dvizhok-progressa-pokazal-vysokiy-uroven-podgotovki-peterburgskih-studentov`,
    "excerpt": `В конце октября в Санкт-Петербурге состоялся конкурс профессионального мастерства для студентов технических колледжей «Движок Прогресса». Одним из организаторов конкурса, проводившегося при поддержке Комитета по труду и занятости и Комитета по образованию Санкт-Петербурга, стала компания «АВТОграф Инструментальные Решения».`,
    "mainImage": `/news/dvizhok-progressa-pokazal-vysokiy-uroven-podgotovki-peterburgskih-studentov.jpg`,
    "content": `Основными задачами конкурсных мероприятий «Движок Прогресса» стала популяризация рабочих профессий среди учащейся молодежи и определение наиболее подготовленных студентов, проходящих обучение именно по тем специальностям, которые наиболее востребованы на промышленных предприятиях Северной столицы.

Не случайно студентам технических колледжей было предложено «померяться силами» в таких номинациях, как «Лучший сварщик», «Лучший мастер слесарных работ», «Лучший сборщик-комплектовщик», «Лучший токарь», «Лучший фрезеровщик», «Лучший маляр промышленный», «Лучший водитель вилочного погрузчика».

Состязания были максимально приближены к реальным производственным условиям. В рамках конкурсного задания студентам нужно было самостоятельно написать управляющую программу и на станках с ЧПУ изготовить деталь для сборки трактора – согласно конструкторской документации, предоставленной Петербургским тракторным заводом.

Соревнования проводились на учебно-производственных площадках СПб ГБПОУ «Автомеханический колледж» и СПб ГБПОУ «Санкт-Петербургский технический колледж», с которыми компанию «АВТОграф Инструментальные Решения» (АИР) связывают многолетние партнерские отношения.

Как один из стратегических партнёров системы профессионального образования, «АВТОграф Инструментальные Решения» активно поддерживает технические колледжи, училища и вузы в вопросах развития материальной базы, и оказывает необходимую помощь в подготовке и проведении чемпионатов, состязаний и других обучающих и конкурсных мероприятий.

Участвуя в проекте «Движок Прогресса», компания АИР предоставила весь необходимый для выполнения конкурсных заданий металлорежущий инструмент и станочную оснастку. Конкурсные площадки также были укомплектованы оборудованием и инструментом для подготовки поверхностей и нанесения лакокрасочных материалов партнера АИР – компании «ВидерКрафт».

В составе экспертов и жюри конкурса, специалисты АИР обеспечивали проведение соревнований и объективную оценку результатов работы студентов.

«Движок Прогресса» завершился торжественной церемонией награждения победителей конкурса, которые добились лучших результатов и продемонстрировали высокий уровень владения современным металлообрабатывающим оборудованием и инструментом, используемым в реальном производстве.`,
    "author": `Редакция`,
    "publishDate": `2022-11-11`,
    "category": `Новости`,
    "seoTitle": `«Движок Прогресса» показал высокий уровень подготовки петербургских студентов`,
