    "excerpt": `С 16 по 18 ноября город Уфа станет центром деловой активности промышленников и машиностроителей всей России! Именно в эти дни, на площадке выставочного комплекса «ВДНХ ЭКСПО», в столице Республики Башкортостан состоятся крупнейшие специализированные выставки «Машиностроение», «Металлообработка» и «Инновационный потенциал Уфы».`,
