    "title": `Метчиковые патроны для нарезания резьбы. Особенности конструкции`,
    "slug": `metchikovye-patrony-dlya-narezaniya-rezby-osobennosti-konstruktsii`,
    "excerpt": `Метчиковый или резьбонарезной патрон – вид фрезерной инструментальной оснастки, используемой для закрепления в шпинделе станка метчика для создания внутренней резьбы в тупиковых и сквозных отверстиях.`,
    "mainImage": `/news/metchikovye-patrony-dlya-narezaniya-rezby-osobennosti-konstruktsii.jpg`,
    "content": `При выполнении работ по нарезанию внутренней резьбы в сквозных и глухих отверстиях на фрезерных станках используются резьбонарезные патроны, разновидностью которых являются метчиковые патроны.

Как следует из названия, метчиковый патрон служит для закрепления метчика в шпинделе станка.

Основное назначение метчикового патрона - компенсация осевых растягивающих и сжимающих нагрузок, возникающих при нарезании резьбы метчиками на станках, не имеющих синхронизации вращения шпинделя и подачи. Как правило, это все универсальные станки.

Осевые растягивающие и сжимающие нагрузки возникают в теле метчика при остановке шпинделя в конце отверстия, смене направления вращения, и выводе метчика из отверстия. Инерция вращения и подачи приводят к неодновременному прекращению вращения шпинделя и подачи метчика, при этом витки нарезанной резьбы ограничивают перемещение метчика, вследствие чего появляются осевые нагрузки.

В конструкции метчикового патрона применяется пружинный компенсатор , позволяющий растянуть или сжать патрон с метчиком на величину:

+/- 7 мм (1 типоразмер вставки, d=19 мм)

+/- 12 мм (2 типоразмер вставки, d=31 мм)

+/- 17,5 мм (3 типоразмер вставки, d=48 мм)

Совместно с метчиковым патроном применяются быстросменные вставки. Каждая вставка изготовлена под конкретный диаметр и квадратную часть хвостовика метчика.

Существует 2 типа и 3 типоразмера метчиковых вставок .

1 тип - Вставка без предохранительной муфты.

2 тип - Вставка с предохранительной муфтой, настроенной на величину крутящего момента метчика, применяемого с этой муфтой.

В ситуации, при которой метчик перестаёт вращаться (например при упоре в дно глухого отверстия или пакетировании стружки), предохранительная муфта начинает проворачиваться, издавая при этом громкие щелчки. Это позволяет оператору вовремя остановить станок и предотвратить аварийный выход из строя метчика, и спасти деталь от порчи резьбового отверстия.

Типоразмеры метчиковых вставок:

1 типоразмер: диаметр посадки в патрон d = 19 мм

2 типоразмер: диаметр посадки в патрон d = 31 мм

3 типоразмер: диаметр посадки в патрон d = 48 мм

Типоразмер вставки должен соответствовать типоразмеру патрона, с которым она используется.`,
