    "excerpt": `В августе в Санкт-Петербурге состоялся VII корпоративный чемпионат профессионального мастерства «Молодые профессионалы Роскосмоса – 2022». Весомый вклад в подготовку и оснащение площадок для проведения профессиональных соревнований среди молодых специалистов отрасли внесла компания «АВТОграф Инструментальные Решения».`,
